program.compute:
options = read('/input/options')
existing = read('/output/selection')
if existing is not None:
    result = existing
else:
    ordered = sorted(options, key=lambda row: [row[field] for field in goal['order_by']])
    result = []
    for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
        for group in combinations(ordered, count):
            candidate = [entry['id'] for entry in group]
            if valid(candidate):
                result = candidate
                break
        if result:
            break

program.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
elif status('report') == 'sent':
    pass
else:
    pass
if exists('/tmp/cache'):
    delete('/tmp/cache')

